CREATE TABLE IF NOT EXISTS price_observations(id bigserial PRIMARY KEY,price_observation_id text UNIQUE,session_id text,market_event_id text,frame_id text,candle_id text,value numeric,observed_at timestamptz,received_at timestamptz,source text,confidence numeric,status text,rejection_reason text,outlier_status text,trace_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS price_observations_session_idx ON price_observations(session_id,observed_at DESC);
CREATE TABLE IF NOT EXISTS ground_truths(id bigserial PRIMARY KEY,ground_truth_id text UNIQUE,session_id text,decision_id text,signal_id text,operation_id text,market_event_id text,entry_price_observation_id text,settlement_price_observation_id text,entry_price numeric,settlement_price numeric,result text,status text,trace_id text,created_at timestamptz NOT NULL DEFAULT now());
